// Generated from rules/classes/red-mage-spells.json; spell effects are manual.
export const redMageSpells=[{"id":"ffd20:spell:alter-food","name":"Alter Food","level":0,"mpCost":0,"summary":"Alter the properties of food to be delicious or disgusting.","url":"https://www.finalfantasyd20.com/magic/spells/a/alter-food/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[A](https://finalfantasyd20.com/magic/spells/a/) >\n\n# Alter Food\n\nTable of Contents\n\n**School** enhancing (cantrip); **Level** [astrologian](https://www.finalfantasyd20.com/classes/base-classes/astrologian/) 0, [black mage](https://www.finalfantasyd20.com/classes/core-classes/black-mage/) 0, [geomancer](https://www.finalfantasyd20.com/classes/base-classes/geomancer/) 0, [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 0, [summoner](https://www.finalfantasyd20.com/classes/base-classes/summoner/) 0, [white mage](https://www.finalfantasyd20.com/classes/core-classes/white-mage/) 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range touch**  \n**Effect 1 lb of edible substances**  \n**Duration when fully consumed or 1 hour after casting**  \n**Saving Throw none**; **Spell Resistance** no\n\n##### DESCRIPTION\n\nYou touch a piece or plate of food, or container of liquid, altering its existence to be either more pleasing or the worst thing someone has ever seen or eaten.\n\nThe affected food or drink can be chilled or heated to comfortable temperatures, have its flavor increase or decreased by 1-star rating (restaurant standards), and even become more rotten or fresh by 1 day per level. This cantrip cannot purify food, however, if the food was already rotten or poisoned it cannot be removed. This spell only affects commonly eaten items, like vegetables, fruit, and meat, or drink such as water, tea, and alcohol, it can affect monster and creature corpses if they are viable for consumption.\n\nIf the caster wishes to spend 1 MP they can increase the effects of this cantrip to almost becoming a true spell, being able to mask the visible signs of poison from its aesthetic or smell, it also alters the star rating of the food by 3 which can make a simple loaf of bread taste like it was made in a high-class bakery, or a steak taste like it came out of the trash.","automation":"manual","archiveSha256":"6ed96d52ed434eb2411439a8977b8b723c0422f685b35c21716df78ef8121cb5","school":"enhancing (cantrip)","castingTime":"1 standard action","spellResistance":"no"},{"id":"ffd20:spell:alter-object","name":"Alter Object","level":0,"mpCost":0,"summary":"Make slight alterations to a single object, or create objects, as a party trick.","url":"https://www.finalfantasyd20.com/magic/spells/a/alter-object/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[A](https://finalfantasyd20.com/magic/spells/a/) >\n\n# Alter Object\n\nTable of Contents\n\n**School** enhancing (cantrip); **Level** [astrologian](https://www.finalfantasyd20.com/classes/base-classes/astrologian/) 0, [black mage](https://www.finalfantasyd20.com/classes/core-classes/black-mage/) 0, [geomancer](https://www.finalfantasyd20.com/classes/base-classes/geomancer/) 0, [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 0, [summoner](https://www.finalfantasyd20.com/classes/base-classes/summoner/) 0, [white mage](https://www.finalfantasyd20.com/classes/core-classes/white-mage/) 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range close (25 ft. + 5 ft./2 levels)**  \n**Effect 1 lb of nonliving material**  \n**Duration 1 hour (D)**  \n**Saving Throw none**; **Spell Resistance** no\n\n##### DESCRIPTION\n\nYou point at an object, altering its physical makeup for up to 1 hour. At the choice of the caster, this cantrip can lift up to 1lb of material, alter its color, chill or warm it 10 degrees, and make slight changes to its shape. The caster may also decide to instead create a crude small object, the object is not overly sophisticated and can be usually examined as artificial., but can be used as a party trick or to impress people.","automation":"manual","archiveSha256":"b8aec28b34e35f81722cbbbcf3a40d6e93e070c0cf42fd0b66faf57e7877e22d","school":"enhancing (cantrip)","castingTime":"1 standard action","spellResistance":"no"},{"id":"ffd20:spell:alleviate","name":"Alleviate","level":0,"mpCost":0,"summary":"Ends a sickened condition for a target.","url":"http://www.finalfantasyd20.com/magic/spells/a/alleviate","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[A](https://finalfantasyd20.com/magic/spells/a/) >\n\n# Alleviate\n\nTable of Contents\n\n**School**healing (cantrip); **Level** red mage 0, white mage 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** touch  \n**Target** creature touched  \n**Duration**instantaneous  \n**Saving Throw**Will negates (harmless); **Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\n*Alleviate* ends a sickened condition for the creature touched. The target cannot be affected again by the same thing that initially sickened them for 24 hours.","automation":"manual","archiveSha256":"41af090770233314248a0fec3b31f354a7c8af8e916696136cea8a69f2f21e75","school":"healing (cantrip)","castingTime":"1 standard action","range":"touch","target":"creature touched","duration":"instantaneous","save":"Will negates (harmless); ","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:burst-of-light","name":"Burst of Light","level":0,"mpCost":0,"summary":"Dazzles one creature (-1 on attack rolls).","url":"http://www.finalfantasyd20.com/magic/spells/b/burst-of-light","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[B](https://finalfantasyd20.com/magic/spells/b/) >\n\n# Burst of Light\n\nTable of Contents\n\n**School**[light](https://www.finalfantasyd20.com/magic/#light) ([cantrip](https://www.finalfantasyd20.com/magic/#cantrip)); **Level** astrologian 0, red mage 0, white mage 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Effect** burst of light  \n**Duration**instantaneous  \n**Saving Throw**Fortitude negates; **Spell Resistance** yes\n\n##### DESCRIPTION\n\nThis cantrip creates a burst of light. If you cause the light to burst in front of a single creature, that creature is [dazzled](https://www.finalfantasyd20.com/magic/status-effects/#dazzled) for 1 minute unless it makes a successful Fortitude save. Sightless creatures, as well as creatures already dazzled, are not affected by burst of light.","automation":"manual","archiveSha256":"d4813700c6a297a4370a391a1c28bf21272502b1f3af97063bd4ce06ee2726d7","school":"light (cantrip)","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","duration":"instantaneous","save":"Fortitude negates; ","spellResistance":"yes"},{"id":"ffd20:spell:dancing-lights","name":"Dancing Lights","level":0,"mpCost":0,"summary":"Creates torches or other lights.","url":"http://www.finalfantasyd20.com/magic/spells/d/dancing-lights","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[D](https://finalfantasyd20.com/magic/spells/d/) >\n\n# Dancing Lights\n\nTable of Contents\n\n**School** [light](https://www.finalfantasyd20.com/magic/#light) (cantrip); **Level** astrologian 0, blue mage 0, [illusionist](https://www.finalfantasyd20.com/classes/base-classes/illusionist/) 0, red mage 0, summoner 0, white mage 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** medium (100 ft. + 10 ft./level)  \n**Target** up to four lights, all within a 10-ft.-radius area  \n**Duration** 1 minute (D)  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nDepending on the version selected, you create up to four lights that resemble lanterns or torches (and cast that amount of light), or up to four glowing spheres of light (which look like will-o’-wisps), or one faintly glowing, vaguely humanoid shape.\n\nThe *dancing lights* must stay within a 10-foot-radius area in relation to each other but otherwise move as you desire (no concentration required): forward or back, up or down, straight or turning corners, or the like.\n\nThe lights can move up to 100 feet per round. A light winks out if the distance between you and it exceeds the spell’s range.\n\nYou can only have one *dancing lights* spell active at any one time. If you cast this spell while another casting is still in effect, the previous casting is dispelled","automation":"manual","archiveSha256":"2766125e05c55f05d9b87ee8d48a6618eab88ade66748bd1f4d130f43aef9256","school":"light (cantrip)","castingTime":"1 standard action","range":"medium (100 ft. + 10 ft./level)","target":"up to four lights, all within a 10-ft.-radius area","duration":"1 minute (D)","save":"none","spellResistance":"no"},{"id":"ffd20:spell:daze","name":"Daze","level":0,"mpCost":0,"summary":"A single humanoid creature with 4 HD or less loses its next action.","url":"http://www.finalfantasyd20.com/magic/spells/d/daze","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[D](https://finalfantasyd20.com/magic/spells/d/) >\n\n# Daze\n\nTable of Contents\n\n**School** enfeebling (cantrip/[compulsion](https://www.finalfantasyd20.com/magic/#compulsion)) [[mind-affecting](https://www.finalfantasyd20.com/magic/#mind-affecting)]; **Level** astrologian 0, black mage 0, blue mage 0, illusionist 0, red mage 0, summoner 0, time mage 0, white mage 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one humanoid creature of 4 HD or less  \n**Duration** 1 round  \n**Saving Throw** Will negates; **Spell Resistance** yes\n\n##### DESCRIPTION\n\nThis spell clouds the mind of a humanoid creature with 4 or fewer Hit Dice so that it takes no actions. Humanoids of 5 or more HD are not affected. A dazed subject is not stunned, so attackers get no special advantage against it. After a creature has been dazed by this spell, it is immune to the effects of this spell for 1 minute.\n\n**Dazed Condition:** The creature is unable to act normally. A dazed creature can take no actions, but has no penalty to AC.","automation":"manual","archiveSha256":"8061f11a7bbad10832a217ab8fa5a27d7f171d4e08b857c854f66cf4d675c273","school":"enfeebling (cantrip/compulsion) [mind-affecting]; ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one humanoid creature of 4 HD or less","duration":"1 round","save":"Will negates","spellResistance":"yes"},{"id":"ffd20:spell:detect-magic","name":"Detect Magic","level":0,"mpCost":0,"summary":"Detects all spells and magic items within 60 ft.","url":"http://www.finalfantasyd20.com/magic/spells/d/detect-magic","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[D](https://finalfantasyd20.com/magic/spells/d/) >\n\n# Detect Magic\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing) (cantrip) [divination]; **Level** astrologian 0, black mage 0, blue mage 0, druid 0, geomancer 0, [illusionist](https://www.finalfantasyd20.com/classes/base-classes/illusionist/) 0, necromancer 0, ninja 0, red mage 0, summoner 0, time mage 0, white mage 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** 60 ft.  \n**Area** cone-shaped emanation  \n**Duration** concentration, up to 1 min./level (D)  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nYou detect magical auras. The amount of information revealed depends on how long you study a particular area or subject.\n\n*1st Round*: Presence or absence of magical auras.\n\n*2nd Round*: Number of different magical auras and the power of the most potent aura.\n\n*3rd Round*: The strength and location of each aura. If the items or creatures bearing the auras are in line of sight, you can make Knowledge (arcana) skill checks to determine the school of magic involved in each. (Make one check per aura: DC 15 + spell level, or 15 + 1/2 caster level for a nonspell effect.) If the aura emanates from a magic item, you can attempt to identify its properties (see Spellcraft). Magical areas, multiple types of magic, or strong local magical emanations may distort or conceal weaker auras.\n\n*Aura Strength*: An aura’s power depends on a spell’s functioning spell level or an item’s caster level; see the accompanying table. If an aura falls into more than one category, *detect magic* indicates the stronger of the two.\n\n## Table: Detect Magic Aura Power\n\n| Spell or Object | Aura Power | | | |\n| --- | --- | --- | --- | --- |\n|  | Faint | Moderate | Strong | Overwhelming |\n| Functioning spell (spell level) | 3rd or lower | 4th-6th | 7th-9th | 10th+ (deity-level) |\n| Magic item (caster level) | 5th or lower | 6th-11th | 12th-20th | 21st+ (artifact) |\n\nLingering Aura: A magical aura lingers after its original source dissipates (in the case of a spell) or is destroyed (in the case of a magic item). If detect magic is cast and directed at such a location, the spell indicates an aura strength of dim (even weaker than a faint aura). How long the aura lingers at this dim level depends on its original power:\n\nOriginal Strength Duration of Lingering Aura  \nFaint 1d6 rounds  \nModerate 1d6 minutes  \nStrong 1d6x10 minutes  \nOverwhelming 1d6 days\n\nOutsiders and elementals are not magical in themselves, but if they are summoned, the spell registers. Each round, you can turn to detect magic in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.","automation":"manual","archiveSha256":"a48ed7898822615e5ef9c15df9f33bf67afcfd1203b4dff45160d512e7957f71","school":"enhancing (cantrip) [divination]","castingTime":"1 standard action","range":"60 ft.","duration":"concentration, up to 1 min./level (D)","save":"none","spellResistance":"no"},{"id":"ffd20:spell:elemental-orb","name":"Elemental Orb","level":0,"mpCost":0,"summary":"Orb deals 1d3 elemental damage of chosen type.","url":"http://www.finalfantasyd20.com/magic/spells/e/elemental-orb","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[E](https://finalfantasyd20.com/magic/spells/e/) >\n\n# Elemental Orb\n\nTable of Contents\n\n**School**elemental (any/cantrip); **Level**black mage 0, blue mage 0, geomancer 0, red mage 0, summoner 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**close (25 ft. + 5 ft./2 levels)  \n**Effect**one missile of chosen element type  \n**Duration**instantaneous  \n**Saving Throw** none;**Spell Resistance** yes\n\n##### DESCRIPTION\n\nPick an element type: earth, fire, ice, lightning, water, or wind. You fire a small orb of that chosen type at the target. You must succeed on a ranged touch attack to hit your target. The orb deals 1d3 points of the chosen elemental damage.\n\nThis cantrip is not potent enough to be able to heal the wounds of creatures that would normally [absorb](https://www.finalfantasyd20.com/magic/elements/#absorption) the element. If a creature with [absorption](https://www.finalfantasyd20.com/magic/elements/#absorption) of the same element is hit by this cantrip they instead just negate the damage.","automation":"manual","archiveSha256":"624751ee6943033486815036cbd8ef7ddbe5e6a22289389a75ea569121bff104","school":"elemental (any/cantrip)","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","duration":"instantaneous","save":"none","spellResistance":"yes"},{"id":"ffd20:spell:gather-coin","name":"Gather Coin","level":0,"mpCost":0,"summary":"Command all nearby coins into your possession.","url":"https://www.finalfantasyd20.com/magic/spells/g/gather-coin/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[G](https://finalfantasyd20.com/magic/spells/g/) >\n\n# Gather Coin\n\nTable of Contents\n\n**School** enhancing (cantrip); **Level** [astrologian](https://www.finalfantasyd20.com/classes/base-classes/astrologian/) 0, [black mage](https://www.finalfantasyd20.com/classes/core-classes/black-mage/) 0, [geomancer](https://www.finalfantasyd20.com/classes/base-classes/geomancer/) 0, [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 0, [summoner](https://www.finalfantasyd20.com/classes/base-classes/summoner/) 0, [white mage](https://www.finalfantasyd20.com/classes/core-classes/white-mage/) 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Target and Area 30ft radius, up to 1lb (50 coins) of coins per level  \nDuration instantaneous**  \n**Saving Throw none**; **Spell Resistance** no\n\n##### DESCRIPTION\n\nWith a snap of the fingers, the caster commands any unattended coins from within a 30ft radius of themselves to float toward them, the coins can be directed ontop of another object, in creatures hands, and/or into bags. This cantrip does not move coins in the possession of other creatures. While moving, the coins may clink against one another or other objects, creating a lot of sounds.","automation":"manual","archiveSha256":"46f1861fb9e4c0085d3eabcd7817d49497e6f7633598ba260b172d80c8dd1d7d","school":"enhancing (cantrip)","castingTime":"1 standard action","spellResistance":"no"},{"id":"ffd20:spell:grab","name":"Grab","level":0,"mpCost":0,"summary":"Able to grab an unattended object up to 5 pounds from close range.","url":"https://www.finalfantasyd20.com/magic/spells/g/grab/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[G](https://finalfantasyd20.com/magic/spells/g/) >\n\n# Grab\n\nTable of Contents\n\n**School** enhancing (cantrip); **Level** black mage 0, red mage 0, time mage 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**close (25 ft. + 5 ft./2 levels)  \n**Target** one non-magical, unattended object weighing up to 5 lbs.  \n**Duration** concentration  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nYou point your finger at an object and can lift it and move it at will from a distance. As a [move action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#move), you can propel the object as far as 15 feet in any direction, though the spell ends if the distance between you and the object ever exceeds the spell’s range.","automation":"manual","archiveSha256":"eefb606ce4173ceed68e56c0985ea4a465086176b4644c73dd04a0e7e9e4a59f","school":"enhancing (cantrip)","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one non-magical, unattended object weighing up to 5 lbs.","duration":"concentration","save":"none","spellResistance":"no"},{"id":"ffd20:spell:guidance","name":"Guidance","level":0,"mpCost":0,"summary":"+1 on one attack roll, saving throw, or skill check.","url":"http://www.finalfantasyd20.com/magic/spells/g/guidance","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[G](https://finalfantasyd20.com/magic/spells/g/) >\n\n# Guidance\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing) ([cantrip](https://www.finalfantasyd20.com/magic/#cantrip)) [divination]; **Level** astrologian 0, blue mage 0, druid 0, geomancer 0, red mage 0, summoner 0, white mage 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** touch  \n**Target** creature touched  \n**Duration** 1 minute or until discharged  \n**Saving Throw** Will negates (harmless); **Spell Resistance** yes\n\n##### DESCRIPTION\n\nThis spell imbues the subject with a touch of divine guidance. The creature gets a +1 competence bonus on a single attack roll, saving throw, or skill check. It must choose to use the bonus before making the roll to which it applies.","automation":"manual","archiveSha256":"b8136f1e6954e2b6106fe6847d11ced41243110b9c10f0ee171e692ee7bb7d49","school":"enhancing (cantrip) [divination]","castingTime":"1 standard action","range":"touch","target":"creature touched","duration":"1 minute or until discharged","save":"Will negates (harmless)","spellResistance":"yes"},{"id":"ffd20:spell:ignite","name":"Ignite","level":0,"mpCost":0,"summary":"Ignites flammable objects.","url":"http://www.finalfantasyd20.com/magic/spells/i/ignite","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[I](https://finalfantasyd20.com/magic/spells/i/) >\n\n# Ignite\n\nTable of Contents\n\n**School** elemental (fire/cantrip); **Level** astrologian 0, black mage 0, blue mage 0, druid 0, geomancer 0, red mage 0, summoner 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one fine object  \n**Duration** instantaneous  \n**Saving Throw** Fortitude negates (object); **Spell Resistance** yes (object)\n\n##### DESCRIPTION\n\nYou can make an unattended Fine flammable object catch on fire. This works as if you were using flint and steel except that you can use *ignite* in any sort of weather and it takes much less time to actually ignite an object.","automation":"manual","archiveSha256":"3c8383f1a6eb38ef6e474ada0f376f964e9332cf0949c250f8a19539cbfd356e","school":"elemental (fire/cantrip)","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one fine object","duration":"instantaneous","save":"Fortitude negates (object)","spellResistance":"yes (object)"},{"id":"ffd20:spell:magical-cleaning","name":"Magical Cleaning","level":0,"mpCost":0,"summary":"Clean a single object of all dirt.","url":"https://www.finalfantasyd20.com/magic/spells/m/magical-cleaning/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[M](https://finalfantasyd20.com/magic/spells/m/) >\n\n# Magical Cleaning\n\nTable of Contents\n\n**School** enhancing (cantrip); **Level** [astrologian](https://www.finalfantasyd20.com/classes/base-classes/astrologian/) 0, [black mage](https://www.finalfantasyd20.com/classes/core-classes/black-mage/) 0, [druid](https://www.finalfantasyd20.com/classes/hybrid-classes/druid/) 0, [geomancer](https://www.finalfantasyd20.com/classes/base-classes/geomancer/) 0, [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 0, [summoner](https://www.finalfantasyd20.com/classes/base-classes/summoner/) 0, [white mage](https://www.finalfantasyd20.com/classes/core-classes/white-mage/) 0\n\n##### CASTING\n\n**Casting Time** 1 [full-round action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#full-round)\n\n##### EFFECT\n\n**Range touch**  \n**Effect one object of up to 1 cubic foot per level**  \n**Duration instantaneous**  \n**Saving Throw none**; **Spell Resistance** no\n\n##### DESCRIPTION\n\nYou surround an object with swirling waters with cleaning agents otherwise harmful to the skin, removing dirt, mud, contaminated substances, disease particles and so on. This spell can remove hard-to-remove stains and even crusted-on-dust of antique items. \n\nIf the caster wishes to spend 1 MP they can increase the effects of this cantrip to almost becoming a true spell, cleaning a 2 cubic feet per level area of objects, flooring, ceiling, and walls. At high enough levels this can clean an entire room in seconds.","automation":"manual","archiveSha256":"298de0380fdc193f3456f2aff399482e8155755603c796601cca1bff8e49dedf","school":"enhancing (cantrip)","castingTime":"1 full-round action","spellResistance":"no"},{"id":"ffd20:spell:magical-hygiene","name":"Magical Hygiene","level":0,"mpCost":0,"summary":"Clean a creature's body of filth, making them fit for a social gathering.","url":"https://www.finalfantasyd20.com/magic/spells/m/magical-hygiene/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[M](https://finalfantasyd20.com/magic/spells/m/) >\n\n# Magical Hygiene\n\nTable of Contents\n\n**School** enhancing (cantrip); **Level** [astrologian](https://www.finalfantasyd20.com/classes/base-classes/astrologian/) 0, [black mage](https://www.finalfantasyd20.com/classes/core-classes/black-mage/) 0, [druid](https://www.finalfantasyd20.com/classes/hybrid-classes/druid/) 0, [geomancer](https://www.finalfantasyd20.com/classes/base-classes/geomancer/) 0, [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 0, [summoner](https://www.finalfantasyd20.com/classes/base-classes/summoner/) 0, [white mage](https://www.finalfantasyd20.com/classes/core-classes/white-mage/) 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range touch**  \n**Target one willing creature**  \n**Duration instantaneous, or 24 hours (D)**  \n**Saving Throw Fortitude negates (harmless)**; **Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\nYou surround one creature with a flurry of shifting waters combined with cleaning chemicals that are non-harmful to the skin and eyes, as well as immediately drying them. This spell removes dirt, sweat, blood stains, foul odors and so on from the creature’s body including their fur or feathers, though not their clothing or gear. After being affected by this spell, the creature has experienced a deep-cleaning, making them presentable for even the highest of society. This spell does not remove the effects of magical substances or otherwise strong effects, like the sticky adhesive of mimics.\n\nIf the caster wishes to spend 1 MP they can increase the effects of this cantrip to almost becoming a true spell, having this cleaning process keep the affected creature clean and pleasingly scented for up to 24 hours, granting them a +1 circumstance bonus on all saving throws against disease and charisma-based skill checks. If the creature is submerged in mud or is otherwise heavily attacked by dirt or foul smells the cantrip is removed.","automation":"manual","archiveSha256":"fdd42220815e2c149fe5e30b062b80f49eff531ebafc19f87339c4e6e84e3c6b","school":"enhancing (cantrip)","castingTime":"1 standard action","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:mending","name":"Mending","level":0,"mpCost":0,"summary":"Makes minor repairs on an object.","url":"http://www.finalfantasyd20.com/magic/spells/m/mending","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[M](https://finalfantasyd20.com/magic/spells/m/) >\n\n# Mending\n\nTable of Contents\n\n**School** healing (cantrip); **Level** astrologian 0, black mage 0, blue mage 0, druid 0, geomancer 0, red mage 0, summoner 0, time mage 0, white mage 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** 10 ft.  \n**Target** one object of up to 1 lb./level  \n**Duration** instantaneous  \n**Saving Throw** Will negates (harmless, object); **Spell Resistance** yes (harmless, object)\n\n##### DESCRIPTION\n\nThis spell repairs damaged objects, restoring 1d4 hit points to the object. If the object has the broken condition, this condition is removed if the object is restored to at least half its original hit points. All of the pieces of an object must be present for this spell to function. Magic items can be repaired by this spell, but you must have a caster level equal to or higher than that of the object. Magic items that are destroyed (at 0 hit points or less) can be repaired with this spell, but this spell does not restore their magic abilities. This spell does not affect creatures (including constructs). This spell has no effect on objects that have been warped or otherwise transmuted, but it can still repair damage done to such items.","automation":"manual","archiveSha256":"7e6194fedad904f2bd7f167b32183e469b76ec09986f1bee33fc18c0fc8bdefc","school":"healing (cantrip)","castingTime":"1 standard action","range":"10 ft.","target":"one object of up to 1 lb./level","duration":"instantaneous","save":"Will negates (harmless, object)","spellResistance":"yes (harmless, object)"},{"id":"ffd20:spell:message","name":"Message","level":0,"mpCost":0,"summary":"Whisper conversation at distance.","url":"http://www.finalfantasyd20.com/magic/spells/m/message","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[M](https://finalfantasyd20.com/magic/spells/m/) >\n\n# Message\n\nTable of Contents\n\n**School** [enfeebling](https://www.finalfantasyd20.com/magic/#enfeebling) (cantrip) [[language-dependent](https://www.finalfantasyd20.com/magic/#language-dependant)]; **Level**[astrologian](https://www.finalfantasyd20.com/classes/base-classes/astrologian/) 0, [black mage](https://www.finalfantasyd20.com/classes/core-classes/black-mage/) 0, [blue mage](https://www.finalfantasyd20.com/classes/base-classes/blue-mage/) 0, [geomancer](https://www.finalfantasyd20.com/classes/base-classes/geomancer/) 0, [necromancer](https://www.finalfantasyd20.com/classes/base-classes/necromancer/) 0, ninja 0, [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 0, [summoner](https://www.finalfantasyd20.com/classes/base-classes/summoner/) 0, [time mage](https://www.finalfantasyd20.com/classes/base-classes/time-mage/) 0, [white mage](https://www.finalfantasyd20.com/classes/core-classes/white-mage/) 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** medium (100 ft. + 10 ft./level)  \n**Target**one creature/level  \n**Duration**10 minutes/level  \n**Saving Throw** none;**Spell Resistance** no\n\n##### DESCRIPTION\n\nYou can whisper messages and receive whispered replies. Those nearby can hear these messages with a DC 25 Perception check. You point your finger at each creature you want to receive the message. When you whisper, the whispered message is audible to all targeted creatures within range. Magical silence, 1 foot of stone, 1 inch of common metal (or a thin sheet of lead), or 3 feet of wood or dirt blocks the spell. The message does not have to travel in a straight line. It can circumvent a barrier if there is an open path between you and the subject, and the path’s entire length lies within the spell’s range. The creatures that receive the message can whisper a reply that you hear. The spell transmits sound, not meaning; it doesn’t transcend language barriers. To speak a message, you must mouth the words and whisper.","automation":"manual","archiveSha256":"a4c1ddc6cf9918f22a93eeef784ce01a5cf44a56293ca3f165534504745f09d0","school":"enfeebling (cantrip) [language-dependent]","castingTime":"1 standard action","range":"medium (100 ft. + 10 ft./level)","target":"one creature/level","duration":"10 minutes/level","save":"none","spellResistance":"no"},{"id":"ffd20:spell:read-magic","name":"Read Magic","level":0,"mpCost":0,"summary":"Read magical scrolls.","url":"http://www.finalfantasyd20.com/magic/spells/r/read-magic","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[R](https://finalfantasyd20.com/magic/spells/r/) >\n\n# Read Magic\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing) (cantrip) [divination]; **Level** [astrologian](https://www.finalfantasyd20.com/classes/base-classes/astrologian/) 0, [black mage](https://www.finalfantasyd20.com/classes/core-classes/black-mage/) 0, [blue mage](https://www.finalfantasyd20.com/classes/base-classes/blue-mage/) 0, [druid](https://www.finalfantasyd20.com/classes/hybrid-classes/druid/) 0, [geomancer](https://www.finalfantasyd20.com/classes/base-classes/geomancer/) 0, [illusionist](https://www.finalfantasyd20.com/classes/base-classes/illusionist/) 0, [necromancer](https://www.finalfantasyd20.com/classes/base-classes/necromancer/) 0, [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 0, [summoner](https://www.finalfantasyd20.com/classes/base-classes/summoner/) 0, [time mage](https://www.finalfantasyd20.com/classes/base-classes/time-mage/) 0, [white mage](https://www.finalfantasyd20.com/classes/core-classes/white-mage/) 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** personal  \n**Target** you  \n**Duration** 10 minutes/level  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nYou can decipher magical inscriptions on objects – books, scrolls, weapons, and the like – that would otherwise be unintelligible. This deciphering does not normally invoke the magic contained in the writing, although it may do so in the case of a cursed or trapped scroll. Furthermore, once the spell is cast and you have read the magical inscription, you are thereafter able to read that particular writing without recourse to the use of read magic. You can read at the rate of one page (250 words) per minute.","automation":"manual","archiveSha256":"63a9e3be389a52855b39be3f76e33c00c7601d919974c9beec21670f5c3a6c11","school":"enhancing (cantrip) [divination]","castingTime":"1 standard action","range":"personal","target":"you","duration":"10 minutes/level","save":"none","spellResistance":"no"},{"id":"ffd20:spell:stabilize","name":"Stabilize","level":0,"mpCost":0,"summary":"Cause a dying creature to stabilize.","url":"http://www.finalfantasyd20.com/magic/spells/s/stabilize","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[S](https://finalfantasyd20.com/magic/spells/s/) >\n\n# Stabilize\n\nTable of Contents\n\n**School**healing (cantrip); **Level** druid 0, geomancer 0, red mage 0, summoner 0, white mage 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target**one living creature  \n**Duration** instantaneous  \n**Saving Throw** Will negates (harmless); **Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\nUpon casting this spell, you target a living creature that has –1 or fewer hit points. That creature is automatically stabilized and does not lose any further hit points. If the creature later takes damage, it continues dying normally.","automation":"manual","archiveSha256":"ff6a08d179f3283b227d866a7fb6fb48470983135b0820e5c24a2c88ccbc95da","school":"healing (cantrip)","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one living creature","duration":"instantaneous","save":"Will negates (harmless); ","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:torchlight","name":"Torchlight","level":0,"mpCost":0,"summary":"Object shines like a torch.","url":"http://www.finalfantasyd20.com/magic/spells/t/torchlight","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[T](https://finalfantasyd20.com/magic/spells/t/) >\n\n# Torchlight\n\nTable of Contents\n\n**School** [light](https://www.finalfantasyd20.com/magic/#light) (cantrip); **Level** astrologian 0, black mage 0, blue mage 0, druid 0, geomancer 0, [illusionist](https://www.finalfantasyd20.com/classes/base-classes/illusionist/) 0, red mage 0, summoner 0, time mage 0, white mage 0\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** touch  \n**Target** object touched  \n**Duration** 10 minutes/level  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nThis spell causes a touched object to glow like a torch, shedding normal light in a 20-foot radius from the point touched, and increasing the light level for an additional 20 feet by one step, up to normal light (darkness becomes dim light, and dim light becomes normal light). In an area of normal or bright light, this spell has no effect. The effect is immobile, but it can be cast on a movable object.\n\nYou can only have one torchlight spell active at any one time. If you cast this spell while another casting is still in effect, the previous casting is dispelled. Torchlight can be used to counter or dispel any darkness spell of equal or lower spell level.","automation":"manual","archiveSha256":"79ce76353a3b98369722ee3da9a1b9125d80978aa924cb7f02a012f00abe0f59","school":"light (cantrip)","castingTime":"1 standard action","range":"touch","target":"object touched","duration":"10 minutes/level","save":"none","spellResistance":"no"},{"id":"ffd20:spell:aero","name":"Aero","level":1,"mpCost":1,"summary":"Ranged touch that deals 1d6 points of wind damage + casting modifier + 1 per level (max of +5) and inflicts Squalled status effect.","url":"http://www.finalfantasyd20.com/magic/spells/a/aero","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[A](https://finalfantasyd20.com/magic/spells/a/) >\n\n# Aero\n\nTable of Contents\n\n**School**elemental (wind); **Level**black mage 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**close (25 ft. + 5 ft./2 levels)  \n**Target**one creature  \n**Duration**instantaneous; 1d4 rounds  \n**Saving Throw**Reflex partial (object — see text);**Spell Resistance** yes (object)\n\n##### DESCRIPTION\n\nYou direct a blast of wind at your opponent. Requires a ranged touch attack roll to hit that deals 1d6 points of wind damage + your casting modifier (Intelligence, Wisdom, or Charisma) + 1 point per caster level (maximum +5) and inflicts the Squalled status effect for 1d4 rounds. A successful Reflex save prevents the status effect from taking effect.\n\nSqualled: Hurricanic winds circle around the creature, pushing back the creature and making it difficult to hear even themselves as their voice is carried into the squall. Squalled creatures suffer from 10% spell failure for spells with somatic and/or vocal components, automatically fail any Perception checks based on sound, and suffer from a cumulative -1 penalty to attacks made within a round (1st attack is -1, 2nd attack is -2 etc).\nEarth spells and effects remove this status effect.","automation":"manual","archiveSha256":"44242bc5585e3276b5529d301d8207e596ea3a53dc41287e8a77a73cb0dc5ec5","school":"elemental (wind); ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"instantaneous; 1d4 rounds","save":"Reflex partial (object — see text)","spellResistance":"yes (object)"},{"id":"ffd20:spell:air-bubble","name":"Air Bubble","level":1,"mpCost":1,"summary":"Provides breathable air for one creature.","url":"http://www.finalfantasyd20.com/magic/spells/a/air-bubble","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[A](https://finalfantasyd20.com/magic/spells/a/) >\n\n# Air Bubble\n\nTable of Contents\n\n**School**[elemental (wind)](https://www.finalfantasyd20.com/magic/#elemental); **Level**black mage 1, druid 1, geomancer 1, red mage 1, white mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**touch  \n**Target**one creature or one object no larger than a large two-handed weapon  \n**Duration**1 minute/level  \n**Saving Throw** [Will](https://www.d20pfsrd.com/gamemastering/combat#TOC-Will) negates (harmless);**Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\nAir bubble creates a small pocket of breathable air that surrounds the touched creature’s head or the touched object. The air bubble allows the creature touched to breathe underwater or in similar airless environments, or protects the object touched from water damage.","automation":"manual","archiveSha256":"cd2c9a62f0d9694ce1d0278cb771d49d48c19c2360fadda61c2be38316d9bc40","school":"elemental (wind)","castingTime":"1 standard action","range":"touch","target":"one creature or one object no larger than a large two-handed weapon","duration":"1 minute/level","save":"Will negates (harmless)","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:alarm","name":"Alarm","level":1,"mpCost":1,"summary":"Wards an area for 2 hours/level.","url":"http://www.finalfantasyd20.com/magic/spells/a/alarm","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[A](https://finalfantasyd20.com/magic/spells/a/) >\n\n# Alarm\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing); **Level** black mage 1, red mage 1, white mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Area** 20-ft.-radius emanation centered on a point in space  \n**Duration** 2 hours/level (D)  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\n*Alarm* creates a subtle ward on an area you select. Once the spell effect is in place, it thereafter sounds a mental or audible alarm each time a creature of Tiny or larger size enters the warded area or touches it. A creature that speaks the password (determined by you at the time of casting) does not set off the *alarm*. You decide at the time of casting whether the *alarm* will be mental or audible in nature.\n\n* *Mental Alarm*: A mental *alarm* alerts you (and only you) so long as you remain within 1 mile of the warded area. You note a single mental “ping” that awakens you from normal sleep but does not otherwise disturb concentration. A silence spell has no effect on a mental *alarm*.\n* *Audible Alarm*: An audible *alarm* produces the sound of a hand bell, and anyone within 60 feet of the warded area can hear it clearly. Reduce the distance by 10 feet for each interposing closed door and by 20 feet for each substantial interposing wall.\n\nIn quiet conditions, the ringing can be heard faintly as far as 180 feet away. The sound lasts for 1 round. Creatures within a silence spell cannot hear the ringing. Ethereal or astral creatures do not trigger the *alarm*.\n\n*Alarm* can be made permanent with a permanency spell.","automation":"manual","archiveSha256":"405e0eabaa5cbd9c24fd2494344ee2b3587bf02994d4eca684ec67460a38c2b0","school":"enhancing","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","duration":"2 hours/level (D)","save":"none","spellResistance":"no"},{"id":"ffd20:spell:bed-of-iron","name":"Bed of Iron","level":1,"mpCost":1,"summary":"You can sleep comfortably in armor without suffering fatigue.","url":"http://www.finalfantasyd20.com/magic/spells/b/bed-of-iron","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[B](https://finalfantasyd20.com/magic/spells/b/) >\n\n# Bed of Iron\n\nTable of Contents\n\n**School** enhancing; **Level** dark knight 1, paladin 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** touch  \n**Target** one creature touched/level  \n**Duration** 8 hours  \n**Saving Throw** Fortitude negates (harmless); **Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\nThis spell makes even the clunkiest armor feel soft as silk to the wearer.\n\nThe subjects of this spell are able to sleep comfortably in medium or heavy armor without suffering from fatig[ue](https://www.d20pfsrd.com/gamemastering/conditions#TOC-Fatigued) the following day.","automation":"manual","archiveSha256":"6935f8dfe8fd92822b5fce6e903b64458aee4e67b9694ae1106fe64adff42f22","school":"enhancing","castingTime":"1 standard action","range":"touch","target":"one creature touched/level","duration":"8 hours","save":"Fortitude negates (harmless); ","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:blizzard","name":"Blizzard","level":1,"mpCost":1,"summary":"Ranged touch that deals 1d6 points of ice damage + casting modifier + 1 per level (max of +5) and inflicts Frozen status effect.","url":"http://www.finalfantasyd20.com/magic/spells/b/blizzard","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[B](https://finalfantasyd20.com/magic/spells/b/) >\n\n# Blizzard\n\nTable of Contents\n\n**School** elemental (ice); **Level** black mage 1, necromancer 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one creature  \n**Duration** instantaneous; 1d4 rounds  \n**Saving Throw** Fortitude partial ([object](https://www.d20pfsrd.com/magic/#:~:text=the%20spell%E2%80%99s%20effect.-,(object),-The%20spell%20can));**Spell Resistance** yes ([object](https://www.d20pfsrd.com/magic/#:~:text=The%20terms%20%E2%80%9C-,object,-%E2%80%9D%20and%20%E2%80%9Charmless%E2%80%9D%20mean))\n\n##### DESCRIPTION\n\nYou direct a blast of ice at your opponent. Requires a ranged touch attack roll to hit that deals 1d6 points of ice damage + your casting modifier (Intelligence, Wisdom, or Charisma) + 1 point per caster level (maximum +5) and inflicts the Frozen status effect for 1d4 rounds. A successful Fortitude save prevents the status effect from taking effect.","automation":"manual","archiveSha256":"c51eb23912b40042aadf83d307912b7b58c4b3bbdcafca5f9348610e9d7c8c49","school":"elemental (ice); ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"instantaneous; 1d4 rounds","save":"Fortitude partial (object,-The%20spell%20can))","spellResistance":"yes (object)"},{"id":"ffd20:spell:blurred-movement","name":"Blurred Movement","level":1,"mpCost":1,"summary":"As blur, but only while you are moving.","url":"http://www.finalfantasyd20.com/magic/spells/b/blurred-movement","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[B](https://finalfantasyd20.com/magic/spells/b/) >\n\n# Blurred Movement\n\nTable of Contents\n\n**School** [illusion](https://www.finalfantasyd20.com/magic/#illusion) ([glamer](https://www.finalfantasyd20.com/magic/#glamer)); **Level** [illusionist](https://www.finalfantasyd20.com/classes/base-classes/illusionist/) 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [swift action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** personal  \n**Target** you  \n**Duration** 1 round/level  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nThis spell functions as [*blur*](https://www.finalfantasyd20.com/magic/spells/b/blur), except that the blurring occurs only when you move at least 10 feet on your turn and ceases at the end of your movement. It is therefore mainly used to protect against attacks on your turn, such as attacks of opportunity. If you move at least twice your speed on your turn, the blurring lasts until the start of your next turn.","automation":"manual","archiveSha256":"43255e03c6e516faf308bd5d9176becfeb01f7725ba1c560d7a6a06f28a20015","school":"illusion (glamer); ","castingTime":"1 swift action","range":"personal","target":"you","duration":"1 round/level","save":"none; ","spellResistance":"no"},{"id":"ffd20:spell:bow-of-the-viera","name":"Bow of the Viera","level":1,"mpCost":1,"summary":"Arrows and bolts do damage as though one size category bigger.","url":"https://www.finalfantasyd20.com/magic/spells/b/bow-of-the-viera/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[B](https://finalfantasyd20.com/magic/spells/b/) >\n\n# Bow of the Viera\n\nTable of Contents\n\n**School**enhancing; **Level** [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 1\n\n##### CASTING\n\n**Casting Time** 1 [[standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)](https://www.d20pfsrd.com/gamemastering/combat#TOC-Standard-Actions)\n\n##### EFFECT\n\n**Range** personal  \n**Targets** you  \n**Duration** 1 minute/level (D)  \n**Saving Throw** [Fortitude](https://www.d20pfsrd.com/gamemastering/combat#TOC-Fortitude) negates (harmless);**Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\nBow of the viera significantly increases the weight and density of arrows or bolts fired from your bow or crossbow the instant before they strike their target and then return them to normal a few moments later.\n\nAny arrow fired from a bow or crossbow you are carrying when the spell is cast deals damage as if one size larger than it actually is. For instance, an arrow fired from a Medium longbow normally deals 1d8 points of damage, but it would instead deal 2d6 points of damage if fired from a longbow affected by bow of the viera (see table on this page for associated increase/decrease in damage due to size change).\n\nOnly you can benefit from this spell. If anyone else uses your bow to make an attack the arrows deal damage as normal for their size. Multiple effects that increase the effective size of a weapon [do not stack](https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9t5u).\n\n## Table: Weapon Damage Size Conversion\n\n| Tiny | Small | Medium | Large | Huge |\n| --- | --- | --- | --- | --- |\n| — | 1 | 1d2 | 1d3 | 1d4 |\n| 1 | 1d2 | 1d3 | 1d4 | 1d6 |\n| 1d2 | 1d3 | 1d4 | 1d6 | 1d8 |\n| 1d3 | 1d4 | 1d6 | 1d8 | 2d6 |\n| 1d4 | 1d6 | 1d8 | 2d6 | 3d6 |\n| 1d6 | 1d8 | 1d10 | 2d8 | 3d8 |\n| 1d8 | 1d10 | 1d12 | 3d6 | 4d6 |\n| 1d4 | 1d6 | 2d4 | 2d6 | 3d6 |\n| 1d8 | 1d10 | 2d6 | 3d6 | 4d6 |\n| 1d10 | 2d6 | 2d8 | 3d8 | 4d8 |\n| 2d6 | 2d8 | 2d10 | 4d8 | 6d8 |","automation":"manual","archiveSha256":"d020ef8773e51a1c3a5a9fa5d3aaae0dd99887b46d35aab7496e1e7c19a2b685","school":"enhancing","castingTime":"1 [standard action](https://www.d20pfsrd.com/gamemastering/combat#TOC-Standard-Actions)","range":"personal","duration":"1 minute/level (D)","save":"Fortitude negates (harmless)","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:call-weapon","name":"Call Weapon","level":1,"mpCost":1,"summary":"Caster makes a weapon fly out of the hands of his ally to himself.","url":"http://www.finalfantasyd20.com/magic/spells/c/call-weapon","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[C](https://finalfantasyd20.com/magic/spells/c/) >\n\n# Call Weapon\n\nTable of Contents\n\n**School** elemental (wind)/summoning; **Level** red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [swift action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#swift)\n\n##### EFFECT\n\n**Range** 30 ft.  \n**Target** one melee weapon wielded by an ally  \n**Duration** instantaneous  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nWhen you cast this spell, a gust of wind wraps around a weapon wielded by an ally within 30 feet to cause it to fly across the space between you and into your open hand. This extra energy persists in the weapon for the rest of the round, granting you a +2 circumstance bonus on attack rolls and weapon damage rolls made during the same round you cast this spell. If the ally targeted for this spell is unwilling to give up her weapon, the spell fails. An unconscious or dying ally is considered a “willing” target so long as the weapon to be called is still in contact with the ally’s body.","automation":"manual","archiveSha256":"b60ee8cdc61dcf5c0ee717d83ebcb842980489df5f3f637f26f7d3426ba1cd92","school":"elemental (wind)/summoning","castingTime":"1 swift action","range":"30 ft.","target":"one melee weapon wielded by an ally","duration":"instantaneous","save":"none","spellResistance":"no"},{"id":"ffd20:spell:choco-feather","name":"Choco Feather","level":1,"mpCost":1,"summary":"Quick reaction to slow a creature’s fall.","url":"http://www.finalfantasyd20.com/magic/spells/c/choco-feather","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[C](https://finalfantasyd20.com/magic/spells/c/) >\n\n# Choco Feather\n\nTable of Contents\n\n**School** enhancing/elemental (wind); **Level** black mage 1, druid 1, red mage 1, white mage 1, geomancer 1\n\n##### CASTING\n\n**Casting Time** 1 [immediate action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#immediate)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one medium or smaller free-falling object or creature  \n**Duration** 1 round/level or until landing  \n**Saving Throw** Will negates (harmless) or Will negates (object); **Spell Resistance** yes (object)\n\n##### DESCRIPTION\n\nThe affected creature or object falls slowly. Choco feather instantly changes the rate at which the target falls to a mere 60 feet per round (equivalent to the end of a fall from a few feet), and the subject takes no damage upon landing while the spell is in effect. When the spell duration expires, a normal rate of falling resumes.\n\nThe spell affects one Medium or smaller creature (including gear and carried objects up to the creature’s maximum load) or object, or the equivalent in larger creatures: a Large creature or object counts as two Medium creatures or objects, a Huge creature or object counts as four Medium creatures or objects, and so forth.\n\nThis spell has no special effect on ranged weapons unless they are falling quite a distance. If the spell is cast on a falling item, the object does half normal damage based on its weight, with no bonus for the height of the drop.\n\nChoco feather works only upon free-falling objects. It does not affect a sword blow or a charging or flying creature.","automation":"manual","archiveSha256":"cef762b4257fb218cb44ea35bf9c42678cb81a8cfe9be763d50a7e0d2cb77f8e","school":"enhancing/elemental (wind); ","castingTime":"1 immediate action","range":"close (25 ft. + 5 ft./2 levels)","target":"one medium or smaller free-falling object or creature","duration":"1 round/level or until landing","save":"Will negates (harmless) or Will negates (object)","spellResistance":"yes (object)"},{"id":"ffd20:spell:cure","name":"Cure","level":1,"mpCost":1,"summary":"Heals 1d6 damage + Casting modifier + 1 per level (max of +5).","url":"http://www.finalfantasyd20.com/magic/spells/c/cure","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[C](https://finalfantasyd20.com/magic/spells/c/) >\n\n# Cure\n\nTable of Contents\n\n**School** healing; **Level** astrologian 1, white mage 1, red mage 1, paladin 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one creature  \n**Duration** instantaneous  \n**Saving Throw** Will half (harmless — see description); **Spell Resistance** yes (harmless — see description)\n\n##### DESCRIPTION\n\nA soft white glow surrounds a wounded living creature, healing for 1d6 points of damage + your casting modifier (Wisdom or Charisma) + 1 point per caster level (maximum +5). Since undead are powered by negative energy, this spell deals damage to them instead of curing their wounds. An undead creature can apply Spell Resistance, and can attempt a Will save to take half damage.","automation":"manual","archiveSha256":"973ae9d90871f16ce3354f69b741a65f1585c34c2a3cc8394b80135365a86284","school":"healing; ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"instantaneous","save":"Will half (harmless — see description)","spellResistance":"yes (harmless — see description)"},{"id":"ffd20:spell:deflect","name":"Deflect","level":1,"mpCost":1,"summary":"Gain a +4 deflection bonus to AC plus an additional +1 per 3 levels against one attack.","url":"http://www.finalfantasyd20.com/magic/spells/d/deflect","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[D](https://finalfantasyd20.com/magic/spells/d/) >\n\n# Deflect\n\nTable of Contents\n\n**School** enhancing; **Level** red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [immediate action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#immediate)\n\n##### EFFECT\n\n**Range** personal  \n**Target** you  \n**Duration** 1 round or until discharged  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nYou project a field of invisible force, creating a short-lived protective barrier. You gain a +4 deflection bonus to your AC against a single attack; this bonus increases by +1 per three caster levels.","automation":"manual","archiveSha256":"e4eb9ae5eb24f9f741804706a3fc0a455dded8995f00efe3bae1e42e3da20a78","school":"enhancing","castingTime":"1 immediate action","range":"personal","target":"you","duration":"1 round or until discharged","save":"none","spellResistance":"no"},{"id":"ffd20:spell:deodorize","name":"Deodorize","level":1,"mpCost":1,"summary":"Subject cannot be tracked by scent.","url":"http://www.finalfantasyd20.com/magic/spells/d/deodorize","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[D](https://finalfantasyd20.com/magic/spells/d/) >\n\n# Deodorize\n\nTable of Contents\n\n**School** enhancing/illusion; **Level** druid 1, illusionist 1, red mage 1, white mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**close (25 ft. + 5 ft./2 levels)  \n**Targets** one creature or object/level touched  \n**Duration** 1 hour/level (D)  \n**Saving Throw** Fortitude negates (harmless); **Spell Resistance:** Yes (harmless)\n\n##### DESCRIPTION\n\nWith a gesture, this spell allows you to dismiss even the foulest or most distinctive scents. When cast, the targeted creatures or objects lose all natural and unnatural odors. A creature under the effect of deodorize cannot be tracked, located, or pinpointed by the scent special quality. In addition, this spell prevents the target creature from using the stench special ability and similar odor-based abilities (such as those possessed by troglodytes). Deodorize does not prevent the target from acquiring outside smells or odors. Dowsing the creature with a pungent substance effectively negates the benefits of the spell until the substance is neutralized or washed away.","automation":"manual","archiveSha256":"04dd4f3f73398664f689e95e0a75dd79eaaff17fb17032f160be69cc03c2cad8","school":"enhancing/illusion","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","duration":"1 hour/level (D)","save":"Fortitude negates (harmless)"},{"id":"ffd20:spell:disappear","name":"Disappear","level":1,"mpCost":1,"summary":"As vanish for 1 round/level (5 max).","url":"http://www.finalfantasyd20.com/magic/spells/d/disappear","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[D](https://finalfantasyd20.com/magic/spells/d/) >\n\n# Disappear\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing)/[illusion](https://www.finalfantasyd20.com/magic/#illusion) ([glamer](https://www.finalfantasyd20.com/magic/#glamer)); **Level** [illusionist](https://www.finalfantasyd20.com/classes/base-classes/illusionist/) 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** touch  \n**Target** creature touched  \n**Duration** 1 round/level (up to 5 rounds) (D)  \n**Saving Throw** Will negates (harmless); **Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\nThis spell functions like [*vanish*](https://www.finalfantasyd20.com/magic/spells/v/vanish), except the effect only lasts for 1 round per caster level (maximum of 5 rounds). Like vanish, the spell immediately ends if the subject attacks any creature.","automation":"manual","archiveSha256":"dc5bc28a88423aa4774aee1087ca4964cc574c2a306bbf93463afe137ddc7fdd","school":"enhancing/illusion (glamer)","castingTime":"1 standard action","range":"touch","target":"creature touched","duration":"1 round/level (up to 5 rounds) (D)","save":"Will negates (harmless)","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:disguise-weapon","name":"Disguise Weapon","level":1,"mpCost":1,"summary":"Changes one weapon's appearance.","url":"http://www.finalfantasyd20.com/magic/spells/d/disguise-weapon","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[D](https://finalfantasyd20.com/magic/spells/d/) >\n\n# Disguise Weapon\n\nTable of Contents\n\n**School** [illusion](https://www.finalfantasyd20.com/magic/#illusion) ([glamer](https://www.finalfantasyd20.com/magic/#glamer)); **Level** [illusionist](https://www.finalfantasyd20.com/classes/base-classes/illusionist/) 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 round\n\n##### EFFECT\n\n**Range** touch  \n**Target** manufactured weapon touched  \n**Duration** 1 hour/level (D)  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nYou make one manufactured weapon look like a different manufactured weapon of the same size and relative encumbrance (light, one-handed, or two-handed). For example, you could make a Small greatsword look like a Small quarterstaff, a Medium club, or a Large dagger. Even the appearance of an improvised weapon is possible. The extent of the apparent change is up to you. You could add or obscure a minor feature or make the item look like it is composed of different materials (stone, wood, adamantine, and so on). The spell does not provide any of the abilities of the chosen form, nor does it alter the perceived tactile or audible properties of the item or how it is wielded. A creature that interacts with the illusion may attempt a Will save to recognize it as an illusion.","automation":"manual","archiveSha256":"9f7f3eacaf08e4cf89e9647ec27d90f415d00218d0b0e1c7d3631793b8e1b0b5","school":"illusion (glamer); ","castingTime":"1 round","range":"touch","target":"manufactured weapon touched","duration":"1 hour/level (D)","save":"none","spellResistance":"no"},{"id":"ffd20:spell:dragon-jump","name":"Dragon Jump","level":1,"mpCost":1,"summary":"Subject gains a +10 enhancement bonus on all Acrobatics checks to jump.","url":"https://www.finalfantasyd20.com/magic/spells/d/dragon-jump/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[D](https://finalfantasyd20.com/magic/spells/d/) >\n\n# Dragon Jump\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing); **Level** [black mage](https://www.finalfantasyd20.com/classes/core-classes/black-mage/) 1, [druid](https://www.finalfantasyd20.com/classes/hybrid-classes/druid/) 1, [geomancer](https://www.finalfantasyd20.com/classes/base-classes/geomancer/) 1, [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 1, [white mage](https://www.finalfantasyd20.com/classes/core-classes/white-mage/) 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one creature  \n**Duration** 1 minute/level (D)  \n**Saving Throw** [Will](https://www.d20pfsrd.com/gamemastering/combat#TOC-Will) negates (harmless); **Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\nThe subject gets a +10 [enhancement bonus](https://www.d20pfsrd.com/basics-ability-scores/glossary#TOC-Enhancement-Bonus) on [Acrobatics](https://www.d20pfsrd.com/skills/acrobatics/) checks made to attempt [high jumps or long jumps](https://www.d20pfsrd.com/skills/Acrobatics/#jumping_and_falling).","automation":"manual","archiveSha256":"c648e81b3c1b1d3d0e2a92d6eef96a03c4e10a5c363687f1f87e189242fcf06c","school":"enhancing; ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"1 minute/level (D)","save":"Will negates (harmless)","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:enlarge","name":"Enlarge","level":1,"mpCost":1,"summary":"[Humanoid](https://www.d20pfsrd.com/bestiary/monster-listings/humanoids/) caster doubles in size.","url":"http://www.finalfantasyd20.com/magic/spells/e/enlarge","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[E](https://finalfantasyd20.com/magic/spells/e/) >\n\n# Enlarge\n\nTable of Contents\n\n**School** enhancing; **Level** red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [swift action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#swift)\n\n##### EFFECT\n\n**Target** personal  \n**Duration** 1 round  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nThis spell causes instant growth of the [humanoid](https://www.d20pfsrd.com/bestiary/monster-listings/humanoids/) caster, doubling its height and multiplying its weight by 8. This increase changes the caster’s size category to the next larger one. The caster gains a +2 size bonus to [Strength](https://www.d20pfsrd.com/basics-ability-scores/ability-scores#TOC-Strength-Str-), a -2 size penalty to [Dexterity](https://www.d20pfsrd.com/basics-ability-scores/ability-scores#TOC-Dexterity-Dex-) (to a minimum of 1), and a -1 penalty on attack rolls and [AC](https://www.d20pfsrd.com/gamemastering/combat#TOC-Armor-Class) due to its increased size.\n\nThe caster whose size increases to Large has a space of 10 feet and a natural reach of 10 feet. This spell does not change the caster’s speed.\n\nIf insufficient room is available for the desired growth, the caster attains the maximum possible size and may make a [Strength](https://www.d20pfsrd.com/basics-ability-scores/ability-scores#TOC-Strength-Str-) check (using its increased Strength) to burst any enclosures in the process. If it fails, it is constrained without harm by the materials enclosing it.\n\nAll equipment worn or carried by the caster is similarly enlarged by the spell. Melee weapons affected by this spell deal more damage (see **Table: Medium/Large Weapon Damage**). Other magical properties are not affected by this spell. Any *enlarged* item that leaves the enlarged caster’s possession (including a projectile or thrown weapon) instantly returns to its normal size. This means that thrown and projectile weapons deal their normal damage. Magical properties of enlarged items are not increased by this spell.\n\nMultiple magical effects that increase size do not stack. This spell only works on creatures of the [humanoid](https://www.d20pfsrd.com/bestiary/monster-listings/humanoids/) type.  \n\n## Table: Medium/Large Weapon Damage\n\n| Medium Weapon Damage | Large Weapon Damage |\n| --- | --- |\n| 1d2 | 1d3 |\n| 1d3 | 1d4 |\n| 1d4 | 1d6 |\n| 1d6 | 1d8 |\n| 1d8 | 2d6 |\n| 1d10 | 2d8 |\n| 1d12 | 3d6 |\n| 2d4 | 2d6 |\n| 2d6 | 3d6 |\n| 2d8 | 3d8 |\n| 2d10 | 4d8 |","automation":"manual","archiveSha256":"3c79a6b6ddabd12ab99f7733cdef2162272aed4ee76522b0db882696bca20970","school":"enhancing; ","castingTime":"1 swift action","target":"personal","duration":"1 round","save":"none; ","spellResistance":"no"},{"id":"ffd20:spell:enspell","name":"Enspell","level":1,"mpCost":1,"summary":"Infuses weapon with elemental damage of +1 per level (max of +5) + your Charisma modifier on next attack.","url":"http://www.finalfantasyd20.com/magic/spells/e/enspell","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[E](https://finalfantasyd20.com/magic/spells/e/) >\n\n# Enspell\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic#enhancing)/[elemental (all)](https://www.finalfantasyd20.com/magic#elemental); **Level** [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 1\n\n##### CASTING\n\n**Casting Time** 1 [swift action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#swift)\n\n##### EFFECT\n\n**Range** [touch](https://www.d20pfsrd.com/magic/#:~:text=%5BSource%5D-,Touch,-You%20must%20touch)  \n**Target** weapon touched  \n**Duration** 1 round/level or until discharged  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nUpon casting this spell, the caster picks an [element](https://www.finalfantasyd20.com/magic/elements/) type (earth, fire, ice, lightning, water, or wind). This spell infuses the weapon touched with elemental energy.\n\nThe next time this weapon strikes a creature, it discharges the elemental energy. The spell deals an extra 1 point of damage of the elemental type chosen per level (to a max of +5) + your Charisma modifier against the target of the attack.\n\nThe weapon loses this property if its wielder drops it or otherwise loses contact with it.","automation":"manual","archiveSha256":"d5c1dc0754c9b2c0f8dbf97683cb20a7763c183c1b18284b65d191fae7ef6dea","school":"enhancing/elemental (all)","castingTime":"1 swift action","range":"touch","target":"weapon touched","duration":"1 round/level or until discharged","save":"none","spellResistance":"no"},{"id":"ffd20:spell:fire","name":"Fire","level":1,"mpCost":1,"summary":"Ranged touch that deals 1d6 points of fire damage + casting modifier + 1 per level (max of +5) and inflicts Burning status effect.","url":"http://www.finalfantasyd20.com/magic/spells/f/fire","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[F](https://finalfantasyd20.com/magic/spells/f/) >\n\n# Fire\n\nTable of Contents\n\n**School**elemental (fire); **Level**black mage 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**close (25 ft. + 5 ft./2 levels)  \n**Target**one creature  \n**Duration**instantaneous; 1d4 rounds  \n**Saving Throw**Reflex partial (see text);**Spell Resistance** yes (object)\n\n##### DESCRIPTION\n\nYou direct a blast of flames at your opponent. Requires a ranged touch attack roll to hit that deals 1d6 points of fire damage + your casting modifier (Intelligence, Wisdom, or Charisma) + 1 point per caster level (maximum +5) and inflicts the Burning status effect for 1d4 rounds. A successful Reflex save prevents the status effect from taking effect.\n\nBurning: A roaring flame surrounds and burns the target. Creatures inflicted with this status take 1d6 + spell level fire damage, and an additional 1d6 + spell level ([Fire III](https://www.finalfantasyd20.com/magic/spells/f/fire-iii) inflicts 1d6+3) at the beginning of each subsequent round. Burning creatures may attempt to make a Reflex save (equal to initial DC) to end the burning status at the beginning of their turns before the subsequent damage would take place.\nIf the creature is able to find a body of water enough to submerge or cover them, the fire is immediately put out, or they can spend 1 round to stop-drop-and-roll to gain a +4 circumstance bonus on their reflex save to end the status.","automation":"manual","archiveSha256":"42d088e59ab4decd76fb825051124e9aeace78aef512b9cf9b02938f2bba0d9d","school":"elemental (fire); ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"instantaneous; 1d4 rounds","save":"Reflex partial (see text)","spellResistance":"yes (object)"},{"id":"ffd20:spell:flame-breath","name":"Flame Breath","level":1,"mpCost":1,"summary":"Caster breathes a cone of fire in 15-ft.-cone burst, dealing 1d4 points of fire damage per level.","url":"http://www.finalfantasyd20.com/magic/spells/f/flame-breath","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[F](https://finalfantasyd20.com/magic/spells/f/) >\n\n# Flame Breath\n\nTable of Contents\n\n**School** elemental (fire); **Level** black mage 1, geomancer 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** 15 ft.  \n**Area** cone-shaped burst  \n**Duration** instantaneous  \n**Saving Throw** Reflex half; **Spell Resistance** yes\n\n##### DESCRIPTION\n\nYou breathe out a cone of searing flame. Any creature in the area of the flames takes 1d4 points of fire damage per caster level (maximum 5d4). Flammable materials burn if the flames touch them. A character can extinguish burning items as a [full-round action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#full-round).","automation":"manual","archiveSha256":"b7b0ff0d20deac70013aba17ab8a45d27ab4863f6289a2b5d4d8b1c6d9bc1fa1","school":"elemental (fire); ","castingTime":"1 standard action","range":"15 ft.","duration":"instantaneous","save":"Reflex half","spellResistance":"yes"},{"id":"ffd20:spell:lead-blades","name":"Lead Blades","level":1,"mpCost":1,"summary":"Melee weapons damage as if one size bigger.","url":"http://www.finalfantasyd20.com/magic/spells/l/lead-blades","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[L](https://finalfantasyd20.com/magic/spells/l/) >\n\n# Lead Blades\n\nTable of Contents\n\n**School**enhancing; **Level** dark knight 1, paladin 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** personal  \n**Target** touch  \n**Duration** 1 minute/level (D)\n\n##### DESCRIPTION\n\nLead blades increases the momentum and density of your melee weapons just as they strike a foe. All melee weapons you are carrying when the spell is cast deal damage as if one size category larger than they actually are. For instance, a Medium longsword normally deals 1d8 points of damage, but it would instead deal 2d6 points of damage if benefiting from lead blades. Only you can benefit from this spell. If anyone else uses one of your weapons to make an attack it deals damage as normal for its size.\n\n## Table: Weapon Damage Size Conversion\n\n| Tiny | Small | Medium | Large | Huge |\n| --- | --- | --- | --- | --- |\n| — | 1 | 1d2 | 1d3 | 1d4 |\n| 1 | 1d2 | 1d3 | 1d4 | 1d6 |\n| 1d2 | 1d3 | 1d4 | 1d6 | 1d8 |\n| 1d3 | 1d4 | 1d6 | 1d8 | 2d6 |\n| 1d4 | 1d6 | 1d8 | 2d6 | 3d6 |\n| 1d6 | 1d8 | 1d10 | 2d8 | 3d8 |\n| 1d8 | 1d10 | 1d12 | 3d6 | 4d6 |\n| 1d4 | 1d6 | 2d4 | 2d6 | 3d6 |\n| 1d8 | 1d10 | 2d6 | 3d6 | 4d6 |\n| 1d10 | 2d6 | 2d8 | 3d8 | 4d8 |\n| 2d6 | 2d8 | 2d10 | 4d8 | 6d8 |","automation":"manual","archiveSha256":"fbf2c737774b65b017c5073b959c5192e3caeb31e665c1d312f1b49412b3c077","school":"enhancing","castingTime":"1 standard action","range":"personal","target":"touch","duration":"1 minute/level (D)"},{"id":"ffd20:spell:longshot","name":"Longshot","level":1,"mpCost":1,"summary":"Caster gains a +10-ft.-bonus to the range increment of any weapon.","url":"http://www.finalfantasyd20.com/magic/spells/l/longshot","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[L](https://finalfantasyd20.com/magic/spells/l/) >\n\n# Longshot\n\nTable of Contents\n\n**School** enhancing; **Level** red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** personal  \n**Target** you  \n**Duration** 1 minute/level  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nThis spell reduces the effect of range, granting a +10-foot bonus to the range increment of any weapon used by the subject.","automation":"manual","archiveSha256":"fb814555754c6f7584d8c12c4fc1506657975c1baf3fe1a5d371f925a7fd0327","school":"enhancing","castingTime":"1 standard action","range":"personal","target":"you","duration":"1 minute/level","save":"none","spellResistance":"no"},{"id":"ffd20:spell:magic-weapon","name":"Magic Weapon","level":1,"mpCost":1,"summary":"Weapon gains +1 bonus.","url":"http://www.finalfantasyd20.com/magic/spells/m/magic-weapon","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[M](https://finalfantasyd20.com/magic/spells/m/) >\n\n# Magic Weapon\n\nTable of Contents\n\n**School**[enhancing](https://www.finalfantasyd20.com/magic/#enhancing); **Level**dark knight 1, paladin 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**touch  \n**Target** weapon touched  \n**Duration**1 minute/level  \n**Saving Throw**Will negates (harmless, object);**Spell Resistance** yes (harmless, object)\n\n##### DESCRIPTION\n\nMagic weapon gives a weapon a +1 [enhancement bonus](https://www.d20pfsrd.com/basics-ability-scores/glossary#TOC-Enhancement-Bonus) on attack and damage rolls. An [enhancement bonus](https://www.d20pfsrd.com/basics-ability-scores/glossary#TOC-Enhancement-Bonus) does not stack with a masterwork weapon’s +1 bonus on attack rolls. You can’t cast this spell on a natural weapon, such as an unarmed strike. This spell only affects [one end of a double-weapon](https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9o9e) as usual.\n\nMultiple enhancement bonuses on the same object do not stack. Only the highest [enhancement bonus](https://www.d20pfsrd.com/basics-ability-scores/glossary#TOC-Enhancement-Bonus) applies.","automation":"manual","archiveSha256":"7d15a495828a188683723edf6a653b00f74110052b7c63286fbc7db563d8aa40","school":"enhancing; ","castingTime":"1 standard action","range":"touch","target":"weapon touched","duration":"1 minute/level","save":"Will negates (harmless, object)","spellResistance":"yes (harmless, object)"},{"id":"ffd20:spell:mount","name":"Mount","level":1,"mpCost":1,"summary":"Summons a yellow chocobo to serve the caster as a mount.","url":"http://www.finalfantasyd20.com/magic/spells/m/mount","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[M](https://finalfantasyd20.com/magic/spells/m/) >\n\n# Mount\n\nTable of Contents\n\n**School** [summoning](https://www.finalfantasyd20.com/magic/#summoning); **Level** astrologian 1, black mage 1, summoner 1, white mage 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 round\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Effect** one mount  \n**Duration** 2 hours/level (D)  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nYou summon a [yellow chocobo](https://www.finalfantasyd20.com/gamemastering/bestiary/magical-beasts/chocobo-family/yellow-chocobo/) to serve you as a mount. The chocobo serves willingly and well. The chocobo comes with a bit and bridle and a riding saddle. The chocobo is not combat-trained, so it will run away if attacked.","automation":"manual","archiveSha256":"5169f6e2e6f2ea92b07a9378e8df6cecb7ae0f15913d577c18acba72487ee5fb","school":"summoning; ","castingTime":"1 round","range":"close (25 ft. + 5 ft./2 levels)","duration":"2 hours/level (D)","save":"none","spellResistance":"no"},{"id":"ffd20:spell:ohspell","name":"Ohspell","level":1,"mpCost":1,"summary":"Converts weapon into elemental damage on next attack.","url":"http://www.finalfantasyd20.com/magic/spells/o/ohspell","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[O](https://finalfantasyd20.com/magic/spells/o/) >\n\n# Ohspell\n\nTable of Contents\n\n**School** enhancing/elemental (all); **Level** red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [swift action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#swift)\n\n##### EFFECT\n\n**Range** touch  \n**Target** weapon touched  \n**Duration** 1 round/level or until discharged  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nUpon casting this spell, the caster picks an elemental type (earth, fire, ice, lightning, water, or wind). This spell infuses the weapon touched with elemental energy. The next time this weapon strikes a creature, it discharges the elemental energy. The weapon deals damage of the elemental type chosen instead of the physical damage it would normally do. The weapon loses this property if its wielder drops it or otherwise loses contact with it.","automation":"manual","archiveSha256":"51e866ada47997c58dfd882f07129a0b7b22dfd95c7ffd2bbb3b511fba4b2642","school":"enhancing/elemental (all); ","castingTime":"1 swift action","range":"touch","target":"weapon touched","duration":"1 round/level or until discharged","save":"none; ","spellResistance":"no"},{"id":"ffd20:spell:poof","name":"Poof!","level":1,"mpCost":1,"summary":"As vanish, except for only 1 round.","url":"https://www.finalfantasyd20.com/magic/spells/p/poof/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[P](https://finalfantasyd20.com/magic/spells/p/) >\n\n# Poof!\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing)/[illusion](https://www.finalfantasyd20.com/magic/#illusion) ([glamer](https://www.finalfantasyd20.com/magic/#glamer)/shadow); **Level** [illusionist](https://www.finalfantasyd20.com/classes/base-classes/illusionist/) 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [swift action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** personal  \n**Target** you  \n**Duration** 1 round (last until the end of the caster’s turn)\n\n##### DESCRIPTION\n\nWhen you cast this spell, you disappear into the shadows. This spell functions like [*vanish*](https://www.finalfantasyd20.com/magic/spells/v/vanish), except the effect only lasts until the end of the caster’s turn. Like vanish, the spell immediately ends if the subject attacks any creature.","automation":"manual","archiveSha256":"59bf8bbe37eb78849530759b83cd700abd8daddb0bf9dbafeb130ece3be134d3","school":"enhancing/illusion (glamer/shadow); ","castingTime":"1 swift action","range":"personal","target":"you","duration":"1 round (last until the end of the caster’s turn)"},{"id":"ffd20:spell:protect","name":"Protect","level":1,"mpCost":1,"summary":"Subject gains a +2 deflect bonus to AC.","url":"http://www.finalfantasyd20.com/magic/spells/p/protect","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[P](https://finalfantasyd20.com/magic/spells/p/) >\n\n# Protect\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing); **Level** [astrologian](http://www.finalfantasyd20.com/classes/base-classes/astrologian/) 1, [paladin](http://www.finalfantasyd20.com/classes/base-classes/paladin/) 1, [red mage](http://www.finalfantasyd20.com/classes/core-classes/red-mage/) 1, [white mage](http://www.finalfantasyd20.com/classes/core-classes/white-mage/) 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one creature  \n**Duration** 3 rounds + 1 round/level (D)  \n**Saving Throw** [Will](https://www.d20pfsrd.com/gamemastering/combat#TOC-Will) negates (harmless);**Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\nThe subject of this spell is protected by a shield that helps deflect physical attacks. The target gains a +2 [deflection bonus](https://www.d20pfsrd.com/basics-ability-scores/glossary#TOC-Deflection-Bonus) to Armor Class for the duration of the spell.","automation":"manual","archiveSha256":"92c9a9503a7f9789ea3e17f509264d9dd75b35ca99fed7fc96a72d55db3970be","school":"enhancing; ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"3 rounds + 1 round/level (D)","save":"Will negates (harmless)","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:quick-step","name":"Quick Step","level":1,"mpCost":1,"summary":"Caster may make two 5-foot steps each round until he attacks or moves more than 5 feet.","url":"http://www.finalfantasyd20.com/magic/spells/q/quick-step","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[Q](https://finalfantasyd20.com/magic/spells/q/) >\n\n# Quick Step\n\nTable of Contents\n\n**School** enhancing; **Level** red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** personal  \n**Target** you  \n**Duration** 1 round/level or until discharged  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nThis spell creates a subtle and complicated force effect that is most effective when used by a still or slow-moving spellcaster. While you are subject to this spell, you can take two 5-foot steps each round and still cast spells and use spell-like abilities without provoking attacks of opportunity. This spell automatically discharges as soon as you make an attack, cast a harmful spell against another creature, or move more than 5 feet with a single [move action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#move). If the action that discharges the spell also provokes attacks of opportunity, that action still provokes attacks of opportunity as normal.","automation":"manual","archiveSha256":"2f3cd9fe7bd3cdaf20cd225769dc447af116d4bf94f49c89789c18fe99524c8d","school":"enhancing","castingTime":"1 standard action","range":"personal","target":"you","duration":"1 round/level or until discharged","save":"none","spellResistance":"no"},{"id":"ffd20:spell:recharge-innate-magic","name":"Recharge Innate Magic","level":1,"mpCost":1,"summary":"Regain one use of all 0 and 1st-level spell-like abilities of a racial trait.","url":"http://www.finalfantasyd20.com/magic/spells/r/recharge-innate-magic/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[R](https://finalfantasyd20.com/magic/spells/r/) >\n\n# Recharge Innate Magic\n\nTable of Contents\n\n**School enhancing**; **Level** astrologian 1, red mage 1, white mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** personal  \n**Target** you  \n**Duration** instantaneous\n\n##### DESCRIPTION\n\nYou channel magic energy into your own aura, recharging your innate magic abilities. You regain one use of all 0-level and 1st-level spell-like abilities you can use as a result of a racial trait.","automation":"manual","archiveSha256":"d4ab5cd14649b214409c15369161b6e0872bedd4be7f4f6cf31850f9ab40a0b3","castingTime":"1 standard action","range":"personal","target":"you","duration":"instantaneous"},{"id":"ffd20:spell:regen","name":"Regen","level":1,"mpCost":1,"summary":"Subject gains Fast Healing 2.","url":"http://www.finalfantasyd20.com/magic/spells/r/regen","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[R](https://finalfantasyd20.com/magic/spells/r/) >\n\n# Regen\n\nTable of Contents\n\n**School** healing/enhancing; **Level**astrologian 1, white mage 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**close (25 ft. + 5 ft./2 levels)  \n**Target** one creature  \n**Duration** 3 rounds + 1 round/level (D)  \n**Saving Throw** Will negates (harmless);**Spell Resistance**yes (harmless)\n\n##### DESCRIPTION\n\nA soft green glow pulses around the subject, healing him over time. For the duration of the spell, the target receives Fast Healing 2 (heals 2 hit points a round).","automation":"manual","archiveSha256":"65309dd4ae69e172d6756681ce23a4b7878fc58432bbea2b04cc9bf04ab281ea","school":"healing/enhancing; ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"3 rounds + 1 round/level (D)","save":"Will negates (harmless)","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:ruin","name":"Ruin","level":1,"mpCost":1,"summary":"1d4+1 damage; +1 missile per two levels above 1st (max 5).","url":"http://www.finalfantasyd20.com/magic/spells/r/ruin","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[R](https://finalfantasyd20.com/magic/spells/r/) >\n\n# Ruin\n\nTable of Contents\n\n**School** [non-elemental](https://www.finalfantasyd20.com/magic/#non-elemental) [[force](https://www.finalfantasyd20.com/magic/#force)]; **Level** black mage 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** medium (100 ft. + 10 ft./level)  \n**Target** up to five creatures, no two of which can be more than 15 ft. apart  \n**Duration** instantaneous  \n**Saving Throw** none; **Spell Resistance** yes\n\n##### DESCRIPTION\n\nA missile of magical energy darts forth from your fingertip and strikes its target, dealing 1d4+1 points of non-elemental damage. The missile strikes unerringly, even if the target is in melee combat, so long as it has less than total cover or total concealment. Specific parts of a creature can’t be singled out. Objects are not damaged by the spell.\n\nFor every two caster levels beyond 1st, you gain an additional missile – two at 3rd level, three at 5th, four at 7th, and the maximum of five missiles at 9th level or higher. If you shoot multiple missiles, you can have them strike a single creature or several creatures. A single missile can strike only one creature. You must designate targets before you check for spell resistance or roll damage.","automation":"manual","archiveSha256":"de54c6bf43e2e2cd424672309ca3bbd7071b4fc62e9f6fdc224ac3e077dbe0e9","school":"non-elemental [force]","castingTime":"1 standard action","range":"medium (100 ft. + 10 ft./level)","target":"up to five creatures, no two of which can be more than 15 ft. apart","duration":"instantaneous","save":"none","spellResistance":"yes"},{"id":"ffd20:spell:saber","name":"Saber","level":1,"mpCost":1,"summary":"For the duration of the spell, you gain a +1 bonus to attack rolls and +2 to damage rolls with any weapon, unarmed strike, or natural attacks.","url":"https://www.finalfantasyd20.com/magic/spells/s/saber/","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[S](https://finalfantasyd20.com/magic/spells/s/) >\n\n# Saber\n\nTable of Contents\n\n**School**enhancing; **Level [black mage](https://www.finalfantasyd20.com/classes/core-classes/black-mage/) 1, [dark knight](https://www.finalfantasyd20.com/classes/base-classes/dark-knight/) 1, [red mage](https://www.finalfantasyd20.com/classes/core-classes/red-mage/) 1**\n\n##### CASTING\n\n**Casting Time** 1 [swift action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#swift)\n\n##### EFFECT\n\n**Range** personal  \n**Target** self  \n**Duration** 1 minute (D)  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nYou direct your magic into guiding and enhancing your physical attacks. For the duration of the spell, you gain a +1 bonus to attack rolls and +2 to damage rolls with any weapon, unarmed strike, or natural attacks. Additionally, they now count as magical attacks for the duration of the spell.\n\nThis spell does not work with [power weapons](https://www.finalfantasyd20.com/equipment/weapons/#ffd20-power-weapons).\n\n*This spell was submitted as a part of the SCC for June 2021 by Drage Enzeru.*","automation":"manual","archiveSha256":"3b5c808d17ca747cefe0913b29f8edacb337c43b7740d7d2b3f869314e7d5b22","school":"enhancing","castingTime":"1 swift action","range":"personal","target":"self","duration":"1 minute (D)","save":"none","spellResistance":"no"},{"id":"ffd20:spell:shell","name":"Shell","level":1,"mpCost":1,"summary":"Subject gains a +2 resistance bonus to saving throws versus spells, spell-like abilities, and supernatural abilities.","url":"http://www.finalfantasyd20.com/magic/spells/s/shell","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[S](https://finalfantasyd20.com/magic/spells/s/) >\n\n# Shell\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing); **Level** [astrologian](http://www.finalfantasyd20.com/classes/base-classes/astrologian/) 1, [paladin](http://www.finalfantasyd20.com/classes/base-classes/paladin/) 1, [red mage](http://www.finalfantasyd20.com/classes/core-classes/red-mage/) 1, [white mage](http://www.finalfantasyd20.com/classes/core-classes/white-mage/) 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one creature  \n**Duration** 3 rounds + 1 round/level (D)  \n**Saving Throw** [Will](https://www.d20pfsrd.com/gamemastering/combat#TOC-Will) negates (harmless); **Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\nThe subject of this spell is protected by a shield that helps protect against magical attacks. The target gains a +2 [resistance bonus](https://www.d20pfsrd.com/basics-ability-scores/glossary#TOC-Resistance-Bonus) to Saving Throws versus spells, spell-like abilities, and supernatural abilities for the duration of the spell.","automation":"manual","archiveSha256":"8072dd4734bd31262dbcff8e394427d3b3d4f80d58549068e3e8e98a847573d4","school":"enhancing; ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"3 rounds + 1 round/level (D)","save":"Will negates (harmless)","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:shield","name":"Shield","level":1,"mpCost":1,"summary":"Invisible disc gives +4 to AC, negates an amount of ruin damage.","url":"http://www.finalfantasyd20.com/magic/spells/s/shield","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[S](https://finalfantasyd20.com/magic/spells/s/) >\n\n# Shield\n\nTable of Contents\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing) [[force](https://www.finalfantasyd20.com/magic/#force)]; **Level**[astrologian](http://www.finalfantasyd20.com/classes/base-classes/astrologian/) 1, [black mage](http://www.finalfantasyd20.com/classes/core-classes/black-mage/) 1, [paladin](http://www.finalfantasyd20.com/classes/base-classes/paladin/) 1, [red mage](http://www.finalfantasyd20.com/classes/core-classes/red-mage/) 1, [time mage](http://www.finalfantasyd20.com/classes/base-classes/time-mage/) 1, [white mage](http://www.finalfantasyd20.com/classes/core-classes/white-mage/) 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**personal  \n**Target**you  \n**Duration** 1 min./level (D) or until discharged.\n\n##### DESCRIPTION\n\nShield creates an invisible shield of force that hovers in front of you. It negates up to 5 points of ruin damage plus an additional 5 points per two caster levels directed at you. Once shield spell absorbs the maximum amount it can, the spell ends. The disk also provides a +4 shield bonus to AC. This bonus applies against incorporeal touch attacks, since it is a force effect. The shield has no armor check penalty or arcane spell failure chance. This spell only affects against the [*Ruin*](https://www.finalfantasyd20.com/magic/spells/r/ruin) spell, not any other higher versions of it.\n\n# Shieldra\n\n**School** [enhancing](https://www.finalfantasyd20.com/magic/#enhancing) [[force](https://www.finalfantasyd20.com/magic/#force)]; **Level** [astrologian](http://www.finalfantasyd20.com/classes/base-classes/astrologian/) 4, [black mage](http://www.finalfantasyd20.com/classes/core-classes/black-mage/) 4, [paladin](http://www.finalfantasyd20.com/classes/base-classes/paladin/) 4, [red mage](http://www.finalfantasyd20.com/classes/core-classes/red-mage/) 4, [time mage](http://www.finalfantasyd20.com/classes/base-classes/time-mage/) 4, [white mage](http://www.finalfantasyd20.com/classes/core-classes/white-mage/) 4\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**close (25 ft. + 5 ft./2 levels)  \n**Target**one creature/two levels (maximum of 5)\n\n##### DESCRIPTION\n\nThis spell functions like [*s**hield*](https://www.finalfantasyd20.com/magic/spells/s/shield), except it affects one creature per two levels (maximum of 5) within 30 feet of each other. This spell works against the [*Ruin**ra*](https://www.finalfantasyd20.com/magic/spells/r/ruinra) and [*Ruinga*](https://www.finalfantasyd20.com/magic/spells/r/ruinga) spells as well as [*Ruin*](https://www.finalfantasyd20.com/magic/spells/r/ruin).","automation":"manual","archiveSha256":"706be76646e633720c3857c1e977f495dbf5209d4158395f9f548bfb2e036f8d","school":"enhancing [force]; ","castingTime":"1 standard action","range":"personal","target":"you","duration":"1 min./level (D) or until discharged."},{"id":"ffd20:spell:shocking-grasp","name":"Shocking Grasp","level":1,"mpCost":1,"summary":"Subject gains a melee touch attack that deals 1d6 points of lightning damage per level.","url":"http://www.finalfantasyd20.com/magic/spells/s/shocking-grasp","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[S](https://finalfantasyd20.com/magic/spells/s/) >\n\n# Shocking Grasp\n\nTable of Contents\n\n**School** elemental (lightning); **Level**black mage 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**touch  \n**Target**one creature or object touched  \n**Duration**instantaneous  \n**Saving Throw**none;**Spell Resistance** yes\n\n##### DESCRIPTION\n\nYour successful melee touch attack deals 1d6 points of lightning damage per caster level (maximum 5d6). When delivering the jolt, you gain a +3 bonus on attack rolls if the opponent is wearing metal armor (or is carrying a metal weapon or is made of metal).","automation":"manual","archiveSha256":"6abf95fda8612333f69ea9057f7757b3fe20c249f3f3ed56bb77ad561c99bc62","school":"elemental (lightning); ","castingTime":"1 standard action","range":"touch","target":"one creature or object touched","duration":"instantaneous","save":"none","spellResistance":"yes"},{"id":"ffd20:spell:shrink","name":"Shrink","level":1,"mpCost":1,"summary":"[Humanoid](https://www.d20pfsrd.com/bestiary/monster-listings/humanoids/) caster decreases in size.","url":"http://www.finalfantasyd20.com/magic/spells/s/shrink","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[S](https://finalfantasyd20.com/magic/spells/s/) >\n\n# Shrink\n\nTable of Contents\n\n**School** enhancing; **Level** red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [swift action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#swift)\n\n##### EFFECT\n\n**Target** personal  \n**Duration** 1 round  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nThis spell causes instant diminution of the humanoid caster, halving its height, length, and width and dividing its weight by 8. This decrease changes the creature’s size category to the next smaller one. The target gains a +2 size bonus to Dexterity, a -2 penalty to Strength (to a minimum of 1), and a +1 bonus on attack rolls and AC due to its reduced size.\n\nA Small humanoid caster whose size decreases to Tiny has a space of 2-1/2 feet and a natural reach of 0 feet (meaning that it must enter an opponent’s square to attack). A Large humanoid caster whose size decreases to Medium has a space of 5 feet and a natural reach of 5 feet. This spell doesn’t change the target’s speed.\n\nAll equipment worn or carried by a creature is similarly reduced by the spell.\n\nMelee and projectile weapons deal less damage. Other magical properties are not affected by this spell. Any *reduced* item that leaves the *reduced* creature’s possession (including a projectile or thrown weapon) instantly returns to its normal size. This means that thrown weapons deal their normal damage (projectiles deal damage based on the size of the weapon that fired them).\n\nMultiple magical effects that reduce size do not stack.  \n\n## Table: Weapon Damage Size Conversion\n\n| Tiny | Small | Medium | Large | Huge |\n| --- | --- | --- | --- | --- |\n| — | 1 | 1d2 | 1d3 | 1d4 |\n| 1 | 1d2 | 1d3 | 1d4 | 1d6 |\n| 1d2 | 1d3 | 1d4 | 1d6 | 1d8 |\n| 1d3 | 1d4 | 1d6 | 1d8 | 2d6 |\n| 1d4 | 1d6 | 1d8 | 2d6 | 3d6 |\n| 1d6 | 1d8 | 1d10 | 2d8 | 3d8 |\n| 1d8 | 1d10 | 1d12 | 3d6 | 4d6 |\n| 1d4 | 1d6 | 2d4 | 2d6 | 3d6 |\n| 1d8 | 1d10 | 2d6 | 3d6 | 4d6 |\n| 1d10 | 2d6 | 2d8 | 3d8 | 4d8 |\n| 2d6 | 2d8 | 2d10 | 4d8 | 6d8 |","automation":"manual","archiveSha256":"45406f3289c54c6b1304d9d2e2484f06abb90a05e1bd5e1b5adc0aae727641ee","school":"enhancing; ","castingTime":"1 swift action","target":"personal","duration":"1 round","save":"none; ","spellResistance":"no"},{"id":"ffd20:spell:stone","name":"Stone","level":1,"mpCost":1,"summary":"Ranged touch that deals 1d6 points of earth damage + casting modifier + 1 per level (max of +5) and inflicts Weighted status effect.","url":"http://www.finalfantasyd20.com/magic/spells/s/stone","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[S](https://finalfantasyd20.com/magic/spells/s/) >\n\n# Stone\n\nTable of Contents\n\n**School** elemental (earth); **Level** black mage 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one creature  \n**Duration** instantaneous; 1d4 rounds  \n**Saving Throw** Fortitude partial (object) — see description; **Spell Resistance** yes (object)\n\n##### DESCRIPTION\n\nYou direct a boulder at your opponent. Requires a ranged touch attack roll to hit that deals 1d6 points of earth damage + your casting modifier (Intelligence or Charisma) + 1 point per caster level (maximum +5) and inflicts the Weighted status effect for 1d4 rounds. A successful Fortitude save prevents the status effect from taking effect.","automation":"manual","archiveSha256":"2c9a7e2f8124c65a818e2fd578faa55de21ca6e5c3336cb3cbb3b6eaee9b3256","school":"elemental (earth); ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"instantaneous; 1d4 rounds","save":"Fortitude partial (object) — see description","spellResistance":"yes (object)"},{"id":"ffd20:spell:stone-fist","name":"Stone Fist","level":1,"mpCost":1,"summary":"Caster transforms his hands into living stone and able to deal lethal unarmed strikes.","url":"http://www.finalfantasyd20.com/magic/spells/s/stone-fist","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[S](https://finalfantasyd20.com/magic/spells/s/) >\n\n# Stone Fist\n\nTable of Contents\n\n**School** enhancing/elemental (earth); **Level**black mage 1, geomancer 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**personal  \n**Target**you  \n**Duration**1 minute/level (D)  \n**Saving Throw**none;**Spell Resistance** no\n\n##### DESCRIPTION\n\nThis spell transforms your hands into living stone. While this spell is in effect, your unarmed strikes do not provoke attacks of opportunity and deal 1d6 points of lethal bludgeoning damage (1d4 if you are Small). In addition, your unarmed strikes ignore the hardness of any object with a hardness less than 8.","automation":"manual","archiveSha256":"037858c886bdf1476c83938078402f5781b19c5ed2879cd73825ea3f8d6f03a4","school":"enhancing/elemental (earth); ","castingTime":"1 standard action","range":"personal","target":"you","duration":"1 minute/level (D)","save":"none","spellResistance":"no"},{"id":"ffd20:spell:stretch","name":"Stretch","level":1,"mpCost":1,"summary":"Melee weapon gains 5 ft. of reach for one attack.","url":"http://www.finalfantasyd20.com/magic/spells/s/stretch","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[S](https://finalfantasyd20.com/magic/spells/s/) >\n\n# Stretch\n\nTable of Contents\n\n**School** enhancing; **Level** red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [swift action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#swift)\n\n##### EFFECT\n\n**Range** touch  \n**Target** weapon touched  \n**Duration** one attack  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nThe affected weapon stretches, extending toward its target, though it can be wielded normally. The spell adds an additional 5 feet of reach to a melee weapon for a single attack.","automation":"manual","archiveSha256":"271018f42871ca37667702925a1e32db7388a325228fbb37a8af1e0ea8d1de5b","school":"enhancing","castingTime":"1 swift action","range":"touch","target":"weapon touched","duration":"one attack","save":"none","spellResistance":"no"},{"id":"ffd20:spell:swim","name":"Swim","level":1,"mpCost":1,"summary":"Subject gains a swim speed of 30 feet.","url":"http://www.finalfantasyd20.com/magic/spells/s/swim","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[S](https://finalfantasyd20.com/magic/spells/s/) >\n\n# Swim\n\nTable of Contents\n\n**School** enhancing/elemental (water); **Level** black mage 1, druid 1, geomancer 1, red mage 1, white mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** touch  \n**Target** creature touched  \n**Duration** 1 minute/level (D)  \n**Saving Throw** Fortitude negates (harmless); **Spell Resistance** yes (harmless)\n\n##### DESCRIPTION\n\nYou cause webs to grow between the target’s fingers and its feet to transform into flippers, granting a swim speed of 30 feet along with the standard +8 bonus on Swim checks and the ability to take 10 even if distracted or endangered. You can also use the run action while swimming, provided you swim in a straight line. This transformation causes any boots or gloves the target is wearing to meld into its form (although magic items with a continuous effect continue to function). This spell does not grant the target any ability to breathe water.","automation":"manual","archiveSha256":"c5c1e7c3a088317503413ddb196af6a2a77def4bfe10e8c58046a8f3dc054ce4","school":"enhancing/elemental (water); ","castingTime":"1 standard action","range":"touch","target":"creature touched","duration":"1 minute/level (D)","save":"Fortitude negates (harmless)","spellResistance":"yes (harmless)"},{"id":"ffd20:spell:thunder","name":"Thunder","level":1,"mpCost":1,"summary":"Ranged touch that deals 1d6 points of lightning damage + casting modifier + 1 per level (max of +5) and inflicts Static status effect.","url":"http://www.finalfantasyd20.com/magic/spells/t/thunder","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[T](https://finalfantasyd20.com/magic/spells/t/) >\n\n# Thunder\n\nTable of Contents\n\n**School** elemental (lightning); **Level** black mage 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one creature  \n**Duration** instantaneous; 1d4 rounds  \n**Saving Throw** Reflex partial (object) — see description; **Spell Resistance** yes (object)\n\n##### DESCRIPTION\n\nYou direct a bolt of lightning at your opponent. Requires a ranged touch attack roll to hit that deals 1d6 points of lightning damage + your casting modifier (Intelligence or Charisma) + 1 point per caster level (maximum +5) and inflicts the Static status effect for 1d4 rounds. A successful Reflex save prevents the status effect from taking effect.","automation":"manual","archiveSha256":"0030f7e92959014b3fc5567cf5119c9666110ca81b056dbea3753a491d1f8eac","school":"elemental (lightning); ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"instantaneous; 1d4 rounds","save":"Reflex partial (object) — see description","spellResistance":"yes (object)"},{"id":"ffd20:spell:water","name":"Water","level":1,"mpCost":1,"summary":"Ranged touch that deals 1d6 points of water damage + casting modifier + 1 per level (max of +5) and inflicts Drenched status effect.","url":"http://www.finalfantasyd20.com/magic/spells/w/water","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[W](https://finalfantasyd20.com/magic/spells/w/) >\n\n# Water\n\nTable of Contents\n\n**School** elemental (water); **Level** black mage 1, red mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** close (25 ft. + 5 ft./2 levels)  \n**Target** one creature  \n**Duration** instantaneous; 1d4 rounds  \n**Saving Throw** Fortitude partial (object) — see description; **Spell Resistance** yes (object)\n\n##### DESCRIPTION\n\nYou direct a blast of pressured water at your opponent. Requires a ranged touch attack roll to hit that deals 1d6 points of water damage + your casting modifier (Intelligence or Charisma) + 1 point per caster level (maximum +5) and inflicts the Drenched status effect for 1d4 rounds. A successful Fortitude save prevents the status effect from taking effect.","automation":"manual","archiveSha256":"39f0c555c21658c219dcf569357b44d28fb70123c0704c5168dc53aa88750903","school":"elemental (water); ","castingTime":"1 standard action","range":"close (25 ft. + 5 ft./2 levels)","target":"one creature","duration":"instantaneous; 1d4 rounds","save":"Fortitude partial (object) — see description","spellResistance":"yes (object)"},{"id":"ffd20:spell:wind-runner","name":"Wind Runner","level":1,"mpCost":1,"summary":"Caster increases his base land speed by 30 feet.","url":"http://www.finalfantasyd20.com/magic/spells/w/wind-runner","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[W](https://finalfantasyd20.com/magic/spells/w/) >\n\n# Wind Runner\n\nTable of Contents\n\n**School** enhancing/elemental (wind); **Level** black mage 1, druid 1, geomancer 1, red mage 1, white mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range** personal  \n**Target** you  \n**Duration** 1 minute/level (D)  \n**Saving Throw** none; **Spell Resistance** no\n\n##### DESCRIPTION\n\nThis spell increases your base land speed by 30 feet. This adjustment is treated as an enhancement bonus. There is no effect on other modes of movement, such as burrow, climb, fly, or swim. As with any effect that increases your speed, this spell affects your jumping distance (see the Acrobatics skill).","automation":"manual","archiveSha256":"4713775d140a5231c911b0a2505d8ff1182c1e2cf3b8873a3fd46c575e8ee1b0","school":"enhancing/elemental (wind); ","castingTime":"1 standard action","range":"personal","target":"you","duration":"1 minute/level (D)","save":"none","spellResistance":"no"},{"id":"ffd20:spell:wind-shield","name":"Wind Shield","level":1,"mpCost":1,"summary":"Caster creates a field of ever-flowing gust of wind around him to deflect ranged attacks.","url":"http://www.finalfantasyd20.com/magic/spells/w/wind-shield","description":"[Home](https://finalfantasyd20.com/) >\n[Magic](https://finalfantasyd20.com/magic/) >\n[Spells](https://finalfantasyd20.com/magic/spells/) >\n[W](https://finalfantasyd20.com/magic/spells/w/) >\n\n# Wind Shield\n\nTable of Contents\n\n**School** enhancing/elemental (wind); **Level**black mage 1, druid 1, geomancer 1, red mage 1, white mage 1\n\n##### CASTING\n\n**Casting Time** 1 [standard action](https://www.finalfantasyd20.com/system-rules/pathfinder-basics/#standard)\n\n##### EFFECT\n\n**Range**personal  \n**Target**you  \n**Duration**1 minute/level (D)  \n**Saving Throw**none;**Spell Resistance** no\n\n##### DESCRIPTION\n\nAn ever-flowing gust of wind surrounds around you. This field deflects incoming arrows, rays, and other ranged attacks. Each ranged attack directed at you for whom the attacker must make an attack roll has a 20% miss chance (similar to the effects of concealment). Other attacks that simply work at a distance are not affected.","automation":"manual","archiveSha256":"e549ab922de9b3c234983acfea7752c8dcc6742bab7cb0c25be8fdd99108541b","school":"enhancing/elemental (wind); ","castingTime":"1 standard action","range":"personal","target":"you","duration":"1 minute/level (D)","save":"none","spellResistance":"no"}];
